1: import { Socket as PhoenixSocket } from "phoenix";
2: import type { PhoenixPayload } from "phoenix";
3: import { authSessionSocketToken } from "@dhc/api-client";
4: 
5: /**
6:  * Notification realtime bridge for NotificationCenter (ALE-164).
7:  *
8:  * Replaces the Supabase-Realtime-backed bridge with a Phoenix-Session-backed
9:  * one. The browser can no longer read the HTTP-only `_dhc_session` cookie to
10:  * pass it as a Phoenix JS `authToken`, and `new WebSocket(url, protocols)`
11:  * has no `withCredentials` so a cross-origin socket cannot send the cookie.
12:  * Instead, the bridge fetches a short-lived, JS-readable socket token from
13:  * `GET /api/auth/socket-token` (credentialed, so the cookie is sent) and
14:  * passes it as `authToken`.
15:  *
16:  * Socket tokens are valid for 60 seconds, and Phoenix JS's own reconnect loop
17:  * reuses the original `authToken`, so the bridge owns recovery (ALE-337).
18:  * Sockets are constructed with a `reconnectAfterMs` that never fires in
19:  * practice, so Phoenix never reconnects by itself. When the live socket
20:  * errors or closes, the bridge leaves its channel, disconnects it, waits a
21:  * bounded backoff, fetches a fresh token, and connects a new socket. Every
22:  * successful (re)join calls `invalidate()` so events missed while
23:  * disconnected are recovered by an authoritative refetch, and resets the
24:  * backoff. A token fetch that hangs past a timeout is abandoned and retried;
25:  * a token that resolves after `destroy()` or after a newer attempt has
26:  * started is dropped. A retired socket that revives itself anyway (Phoenix's
27:  * heartbeat-timeout or `pageshow` paths) is disconnected again on its next
28:  * lifecycle event.
29:  *
30:  * The channel carries only a best-effort `notification_created` invalidation
31:  * signal; notification data, pagination, and unread counts remain owned by
32:  * the Phoenix HTTP API.
33:  *
34:  * The bridge is best-effort: connection, authentication, join, and reconnect
35:  * failures never throw to the caller. They emit diagnostic warnings and are
36:  * retried with backoff (a failed or empty token fetch included), except a
37:  * rejected HTTP session, which ends this bridge until it is mounted again. Channel
38:  * rejoin on a still-connected socket is left to Phoenix: it needs no token,
39:  * only schedules while the socket is connected, and the bridge leaves the
40:  * channel before retiring its socket, so the two never compete. HTTP queries and
41:  * mutations remain usable regardless of realtime state.
42:  */
43: 
44: export type InvalidateNotifications = () => void;
45: 
46: /**
47:  * Fetches a short-lived Phoenix socket token. `null` is temporarily unavailable;
48:  * an unauthorized session ends recovery. HTTP queries remain independent.
49:  */
50: export const socketSessionUnauthorized = Symbol("socket-session-unauthorized");
51: export type SocketTokenFetcher = () => Promise<
52: 	string | null | typeof socketSessionUnauthorized
53: >;
54: 
55: /**
56:  * Factory that constructs a Phoenix `Socket`. Injected so tests can substitute
57:  * the client boundary without importing the real `phoenix` package.
58:  */
59: export interface RealtimePush {
60: 	receive(
61: 		status: string,
62: 		callback: (response: PhoenixPayload) => void,
63: 	): RealtimePush;
64: 	send(timeout?: number): RealtimePush;
65: }
66: 
67: export interface RealtimeChannel {
68: 	readonly topic: string;
69: 	join(timeout?: number): RealtimePush;
70: 	leave(timeout?: number): RealtimePush;
71: 	on(
72: 		event: string,
73: 		callback: (payload: PhoenixPayload, ref?: string) => void,
74: 	): string;
75: }
76: 
77: export interface RealtimeSocket {
78: 	connect(): void;
79: 	disconnect(callback?: () => void, code?: number, reason?: string): void;
80: 	channel(topic: string): RealtimeChannel;
81: 	onError(callback: (reason?: string) => void): string;
82: 	onClose(callback: () => void): string;
83: 	onOpen(callback: () => void): string;
84: }
85: 
86: export interface RealtimeSocketOptions {
87: 	authToken: string;
88: 	/**
89: 	 * Phoenix's own reconnect delay. The bridge owns recovery, so this keeps
90: 	 * Phoenix's reconnect timer from firing within any realistic page life.
91: 	 */
92: 	reconnectAfterMs: (tries: number) => number;
93: }
94: 
95: export type SocketFactory = (
96: 	url: string,
97: 	options: RealtimeSocketOptions,
98: ) => RealtimeSocket;
99: 
100: export interface NotificationRealtimeConfig {
101: 	/** Public Phoenix WebSocket socket URL, e.g. `wss://host/socket`. */
102: 	socketUrl: string;
103: 	/** Fetches a short-lived Phoenix socket token (via the session cookie). */
104: 	getSocketToken?: SocketTokenFetcher;
105: 	/** Invalidates the Notifications infinite-query key (authoritative refetch). */
106: 	invalidate: InvalidateNotifications;
107: 	/** Constructs the Phoenix Socket. Defaults to the real `phoenix` client. */
108: 	createSocket?: SocketFactory;
109: }
110: 
111: export interface NotificationRealtimeHandle {
112: 	/** Tear down channel and disconnect socket. Idempotent. */
113: 	destroy: () => void;
114: }
115: 
116: const NOTIFICATION_CREATED_EVENT = "notification_created";
117: 
118: /**
119:  * Delay before each consecutive reconnect attempt. The last entry is the
120:  * ceiling, so a failing token endpoint is hit at most every 30 seconds.
121:  */
122: const RECONNECT_BACKOFF_MS = [1_000, 2_000, 5_000, 10_000, 30_000] as const;
123: 
124: /** A token fetch that hasn't settled by now is abandoned and retried. */
125: const TOKEN_FETCH_TIMEOUT_MS = 10_000;
126: 
127: /**
128:  * Largest delay `setTimeout` honours (~24.8 days). Larger values, including
129:  * `Infinity`, overflow and fire immediately, so this is the "never" handed to
130:  * Phoenix's reconnect timer.
131:  */
132: const NEVER_MS = 2_147_483_647;
133: 
134: const defaultCreateSocket: SocketFactory = (url, options) => {
135: 	// Imported at module top-level so Vite bundles the real `phoenix` client.
136: 	// Tests inject a substitute via `createSocket`, so this default never runs
137: 	// under test.
138: 	return new PhoenixSocket(url, options);
139: };
