141: const defaultGetSocketToken: SocketTokenFetcher = async () => {
142: 	const { data, error, response } = await authSessionSocketToken();
143: 	if (response?.status === 401) return socketSessionUnauthorized;
144: 	return error || !data ? null : data.data.socketToken;
145: };
