151: /**
152:  * Connect a Phoenix Socket, join the user's Notification topic, and keep it
153:  * connected. Every connect (initial and recovery) fetches a fresh socket
154:  * token because the token is short-lived; a socket error or close replaces
155:  * the socket after a bounded backoff.
156:  *
157:  * Returns a handle whose `destroy()` cancels any pending reconnect, leaves
158:  * the channel, and disconnects the socket. All realtime failures are
159:  * swallowed and logged; `invalidate` is only ever called as a best-effort
160:  * refetch trigger, never as an error path.
161:  *
162:  * The `userId` (topic suffix) is read from the decoded socket token —
163:  * Phoenix assigns `current_user.sub` on connect, and the channel join
164:  * authorizes the topic against that sub. The browser does not need to know
165:  * its own user id here; it learns the topic from the server's join response.
166:  */
167: export function connectNotificationRealtime(
168: 	config: NotificationRealtimeConfig,
169: ): NotificationRealtimeHandle {
170: 	const {
171: 		socketUrl,
172: 		getSocketToken = REDACTED,
173: 		invalidate,
174: 		createSocket = defaultCreateSocket,
175: 	} = config;
