205: 							class="flex items-center gap-3 px-4 py-3 border-b border-border hover:bg-muted transition-colors"
206: 						>
207: 							{#if !notification.read_at}
208: 								<div
209: 									class="w-2 h-2 rounded-full bg-red-500 flex-shrink-0"
210: 								></div>
211: 							{:else}
212: 								<div class="w-2 h-2 flex-shrink-0"></div>
213: 							{/if}
214: 							<div class="flex-1 min-w-0">
215: 								<p class="m-0 text-sm leading-normal">{notification.body}</p>
216: 								<span class="text-xs text-muted-foreground block"
217: 									>{formatTime(notification.created_at)}</span
218: 								>
219: 							</div>
220: 							{#if !notification.read_at}
221: 								<Button
222: 									variant="ghost"
223: 									size="icon-sm"
224: 									class="flex-shrink-0 rounded-full text-primary"
225: 									onclick={() =>
226: 										markAsRead.mutate({ path: { id: notification.id } })}
227: 								>
228: 									<span class="sr-only">Mark as read</span>
229: 									<Eye aria-hidden="true" />
230: 								</Button>
231: 							{/if}
232: 						</div>
233: 					{/each}
234: 
235: 					{#if notificationsQuery.hasNextPage}
236: 						<Button
237: 							variant="ghost"
238: 							class="w-full rounded-none text-primary"
239: 							onclick={() => notificationsQuery.fetchNextPage()}
240: 							disabled={notificationsQuery.isFetchingNextPage}
241: 						>
242: 							{notificationsQuery.isFetchingNextPage
243: 								? "Loading more..."
