  },
}).provide({
  actors: {
    worker: fromPromise(async ({ input, emit, self }) => {
      console.log('self is actor?', typeof self.send, 'emit?', typeof emit);
      setTimeout(() => { try { emit({ type: 'PING' }); } catch (e) { console.log('emit threw:', e.message); } input.report({ type: 'PING' }); }, 10);
      return 'done-value';
    }),
  },
});
const actor = createActor(m);
actor.start();
await new Promise(r => setTimeout(r, 20));
actor.send({ type: 'GO' });
// late emit from the already-stopped promise actor:
setTimeout(() => {}, 0);
console.log('emitted:', emitted);
console.log('status:', actor.getStatus());
